Det mesta av godset stannar i länet. Två tredjedelar av det som lastas i Halland lossas också i Halland, vilket stämmer med att det mesta lastbilsgodset körs kort. Av det som går över länsgränsen är flödena till och från Västra Götaland och Skåne störst. Av det gods som lastas i Halland går 14 procent till Västra Götaland och 9 procent till Skåne, och av det som lossas i länet kommer 18 procent från Västra Götaland och 8 procent från Skåne. Halland tar alltså emot mer gods från Västra Götaland än det skickar dit.

godsRelationer = {
  const kort = { "Hallands län": "Inom Halland", "Västra Götalands län": "Västra Götaland", "Skåne län": "Skåne",
                 "Jönköpings län": "Jönköping", "Kronobergs län": "Kronoberg" };
  const rader = [];
  for (const [ri, namn] of [["fran_halland", "Lastat i Halland, lossat i"], ["till_halland", "Lossat i Halland, lastat i"]]) {
    const r = lastbilRelationer.filter(d =&gt; d.riktning === ri && d.ar === 2025 && d.matt === "ton_medel3");
    const grupper = d3.rollup(r, v =&gt; d3.sum(v, d =&gt; d.varde), d =&gt; kort[d.motpart_namn] ?? "Övriga län");
    const tot = d3.sum(grupper.values());
    for (const [g, v] of grupper) rader.push({ riktning: namn, motpart: g, andel: 100 * v / tot, antal: v / 1000 });
  }
  return rader;
}

