  const namnFor = new Map(Object.entries(kod).map(([n, k]) =&gt; [k, n]));
  const bost = byggnaderTypAlla
    .filter(d =&gt; d.byggnadstyp === "bostad" && namnFor.has(d.region_kod))
    .map(d =&gt; ({ år: d.ar, serie: namnFor.get(d.region_kod), värde: d.markyta_m2_per_invanare }));
  const beb = bebyggdPerInv
    .filter(d =&gt; namnFor.has(d.region_kod))
    .map(d =&gt; ({ år: d.ar, serie: namnFor.get(d.region_kod), värde: d.bebyggd_m2_per_invanare }));
  const bostMark = bebyggdPerInv
    .filter(d =&gt; namnFor.has(d.region_kod))
    .map(d =&gt; ({ år: d.ar, serie: namnFor.get(d.region_kod), värde: d.bostadsmark_m2_per_invanare }));
  const fmtM = d =&gt; Math.round(d).toLocaleString("sv-SE") + " m²";
  return [
    { key: "bost", label: "Bostadshusens markyta per invånare", filterLabel: "Bostadshusens markyta per invånare",
      subtitle: "Markyta under bostadshus, kvadratmeter per invånare, 2010–2025",
      data: bost, yLabel: "m² per invånare", yMin: 30, formatY: fmtM },
    { key: "beb", label: "Bebyggd mark per invånare", filterLabel: "Bebyggd och anlagd mark per invånare",
      subtitle: "All bebyggd och anlagd mark (byggnader, tomter, vägar, anläggningar), kvadratmeter per invånare, 2010, 2015 och 2020",
