  const etikett = new Map([
    ["Minst 4 avgångar i timmen", "Minst 4 avgångar i timmen"],
    ["2-4 avgångar i timmen", "2–4 avgångar i timmen"],
    ["1-2 avgångar i timmen", "1–2 avgångar i timmen"],
    ["Under en avgång i timmen", "Under 1 avgång i timmen"],
