  const rad = (d) =&gt; ({ region: d.region_namn, klass: etikett.get(d.klass), andel: d.andel });
  return {
    klasser: klasser.map(k =&gt; etikett.get(k)),
    kommun: kollektivTurtathet.filter(d =&gt; d.region_typ !== "typologi").map(rad)
