    { kod: "1381", namn: "Laholm" },
    { kod: "1315", namn: "Hylte" },
    { kod: "0000", namn: "Riket" }
  ];
  return regioner.map(r =&gt; {
    const rader = personerBoendeformAlder.filter(d =&gt; d.region_kod === r.kod && boendeGruppOrdning.includes(d.boendegrupp));
    const tot = d3.rollup(rader, v =&gt; d3.sum(v, d =&gt; d.antal), d =&gt; d.ald_klass);
    return {
      key: r.kod, label: r.namn,
      subtitle: `Andel av invånarna i varje åldersklass efter boendeform, ${r.namn} 2025. Region väljs i rullgardinen.`,
      data: rader.map(d =&gt; ({ ald_klass: d.ald_klass, boendegrupp: d.boendegrupp, antal: d.antal,
                              andel: tot.get(d.ald_klass) &gt; 0 ? 100 * d.antal / tot.get(d.ald_klass) : 0 }))
    };
  });
}

