Följer man takten i femårssteg blir inbromsningen tydlig. Under tillväxtåren låg den på mellan fyra och sju procent per femårsperiod, med toppen 2015–2020 på sju procent. Redan under den senaste uppmätta perioden, 2020–2025, sjönk den till knappt tre procent, och prognosen pekar mot ännu lägre nivåer: drygt en procent 2025–2030 och därefter en svag ökning till omkring en och en halv procent fram till 2040. Takten väntas alltså stabiliseras långt under den nivå länet har varit van vid, men för Halland som helhet vänder den inte till minskning.

Kommunerna går isär

Bakom länets siffra finns stora skillnader mellan kommunerna, och prognosen förändrar delvis bilden av var i Halland tillväxten sker. Den tydligaste förändringen är att Varberg väntas stå för en allt större del av tillväxten. Kommunen beräknas växa med drygt 6 300 invånare till 2040, drygt nio procent, och svarar därmed ensam för nära hälften av länets beräknade tillväxt. Det fortsätter den förskjutning söderut som redan syns i utfallet, där Varberg på senare år har gått om Kungsbacka som länets snabbast växande kommun. Halmstad och Falkenberg väntas växa med drygt fyra procent var och står tillsammans för knappt hälften av ökningen, så att kuststäderna fortsätter att stå för det mesta av utvecklingen.

prognosKommun = {
  const komm = ["Kungsbacka", "Varberg", "Falkenberg", "Halmstad", "Laholm", "Hylte"];
  const index = [], takt = [], taktAntal = [];
  for (const k of komm) {
    const s = prognos.filter(d =&gt; d.region === k).sort((a, b) =&gt; a.år - b.år);
    const popAt = new Map(s.map(d =&gt; [d.år, d.befolkning]));
    const p00 = popAt.get(2000);
    for (const d of s) {
      index.push({ år: d.år, serie: k, värde: 100 * d.befolkning / p00 });
      const prev = popAt.get(d.år - 1);
      if (prev) {
        takt.push({ år: d.år, serie: k, värde: Math.round(1000 * (d.befolkning / prev - 1)) / 10 });
        taktAntal.push({ år: d.år, serie: k, värde: d.befolkning - prev });
      }
    }
  }
  return [
    {
      key: "index", label: "Index (2000 = 100)", filterLabel: "Index (2000 = 100)",
      subtitle: "Index 100 = år 2000. Utfall 2000–2025, prognos 2025–2040.", data: index,
      yLabel: "Index", yMin: "auto", hline: { value: 100, dashed: true }, formatY: d =&gt; d.toFixed(0)
    },
    {
      key: "takt", label: "Årlig befolkningsförändring", filterLabel: "Årlig förändring (%)",
      subtitle: "Procentuell förändring per år. Utfall 2001–2025, prognos 2025–2040.", data: takt,
      yLabel: "% per år", yMin: "auto", hline: { value: 0, dashed: true },
      formatY: d =&gt; d.toLocaleString("sv-SE", { minimumFractionDigits: 1, maximumFractionDigits: 1 }) + " %"
    },
    {
      key: "taktAntal", label: "Årlig befolkningsförändring", filterLabel: "Årlig förändring (antal)",
      subtitle: "Förändring i antal invånare per år. Utfall 2001–2025, prognos 2025–2040.", data: taktAntal,
      yLabel: "Invånare per år", yMin: "auto", hline: { value: 0, dashed: true },
      formatY: d =&gt; (d &gt; 0 ? "+" : "") + d.toLocaleString("sv-SE")
    }
  ];
}

