// Flera DeSO delar RegSO-namn ("Andersberg"): numrera dubbletterna så att etiketterna blir unika
unikaNamn = rows =&gt; {
  const n = d3.rollup(rows, v =&gt; v.length, d =&gt; d.omrade + "|" + d.kommun);
  const i = new Map();
  return [...rows].sort((a, b) =&gt; d3.ascending(a.desokod, b.desokod)).map(d =&gt; {
    const k = d.omrade + "|" + d.kommun;
    if (n.get(k) === 1) return { ...d, namn: `${d.omrade} (${d.kommun})` };
    i.set(k, (i.get(k) || 0) + 1);
    return { ...d, namn: `${d.omrade} ${i.get(k)} (${d.kommun})` };
  });
}

